// Retail-only estimation, product master, tagging and chit workflows.
const RC_VERSION='2.10.4';
let rcSection='Bill',rcChitTab='Group',rcProductEdit='',rcTagEdit='',rcEstimateEdit='';
const RC_SECTIONS=['Bill','Sales Return','Receipt','Advance Amount','Metal Weight Advance'];
function rcAllowed(){return !!(session&&goldleafContext?.has_access&&goldleafContext.retail_enabled&&!erpIsAdmin()&&workspaceMode==='retail')}
function rcEnsure(){if(!Array.isArray(db.retailDocuments))db.retailDocuments=[];}
function rcSaveStatus(promise,label){const show=()=>{const status=document.getElementById('cloudState')?.textContent||'';say(/^Cloud(?: sync)? ·/.test(status)?label+' saved to cloud.':(status.startsWith('Sync issue')||status.startsWith('Entry saved here'))?'Saved on this device only. Cloud sync failed: '+(window.v2LastSyncError||'check Settings → Cloud account.'):label+' saved on this device. Sign in to sync across devices.')};if(promise&&typeof promise.then==='function')promise.then(show);else show()}
function rcDocs(kind){rcEnsure();return db.retailDocuments.filter(x=>x.kind===kind)}
function rcRows(){return [...document.querySelectorAll('#rcItems .rc-item')].map((row)=>{const g=k=>row.querySelector('[data-rc="'+k+'"]').value;return rbItemCalc({id:row.dataset.id||crypto.randomUUID(),product:g('product'),pieces:g('pieces'),grossWeight:g('grossWeight'),lessWeight:g('lessWeight'),purity:g('purity'),wastage:g('wastage'),rate:g('rate'),makingMode:'piece',makingRate:g('makingRate'),tagCode:g('tagCode')})})}
function rcItemRow(x={}){const products=rcDocs('retail-product'),name=String(x.product||''),purity=Number(x.purity||22),rate=n(x.rate)||v2RateForPurity(purity),tags=rcDocs('retail-tagging').filter(t=>t.status==='In stock'||t.tagCode===x.tagCode);return '<div class="rc-item" data-id="'+esc(x.id||crypto.randomUUID())+'"><label>Product<select data-rc="product" required><option value="">Select product</option>'+[...new Set([...products.map(p=>p.name),...db.products,name].filter(Boolean))].map(p=>'<option '+(p===name?'selected':'')+'>'+esc(p)+'</option>').join('')+'</select></label><label>Tag / barcode<select data-rc="tagCode" onchange="rcApplyTag(this)"><option value="">No tag</option>'+tags.map(t=>'<option value="'+esc(t.tagCode)+'" '+(x.tagCode===t.tagCode?'selected':'')+'>'+esc(t.tagCode)+' · '+esc(t.product)+'</option>').join('')+'</select></label><label>Pieces<input data-rc="pieces" type="number" min="1" step="1" value="'+(x.pieces||1)+'"></label><label>Gross g<input data-rc="grossWeight" type="number" min="0.001" step=".001" required value="'+(x.grossWeight??x.weight??'')+'"></label><label>Less g<input data-rc="lessWeight" type="number" min="0" step=".001" value="'+(x.lessWeight||0)+'"></label><label>Purity K<input data-rc="purity" type="number" min="1" max="24" step=".01" value="'+purity+'"></label><label>Wastage %<input data-rc="wastage" type="number" min="0" max="100" step=".01" value="'+(x.wastage||0)+'"></label><label>Rate / g ₹<input data-rc="rate" type="number" min="0" step=".01" value="'+rate+'"></label><label>Making / piece ₹<input data-rc="makingRate" type="number" min="0" step=".01" value="'+(x.makingRate||0)+'"></label><output class="rc-line-value">'+rateMoney(rbItemCalc(Object.assign({},x,{purity,rate})).subtotal)+'</output><button type="button" aria-label="Remove item" onclick="rcRemoveItem(this)">Remove</button></div>'}
window.rcApplyTag=function(select){const t=rcDocs('retail-tagging').find(x=>x.tagCode===select.value),row=select.closest('.rc-item');if(!t||!row)return;for(const [k,v] of Object.entries({product:t.product,pieces:t.pieces,grossWeight:t.grossWeight,lessWeight:t.lessWeight,purity:t.purity,wastage:t.wastage,rate:t.rate,makingRate:t.makingRate})){const el=row.querySelector('[data-rc="'+k+'"]');if(el)el.value=v}row.closest('form').dataset.entryDirty='1';rcRecalc()};
const rcPriorItemMarkup=window.rbItemMarkup;window.rbItemMarkup=function(item,index){const html=rcPriorItemMarkup(item,index);if(workspaceMode!=='retail')return html;const options=[...new Set([...db.products,...rcDocs('retail-product').map(p=>p.name),item.product].filter(Boolean))].map(p=>'<option value="'+esc(p)+'" '+(p===item.product?'selected':'')+'>'+esc(p)+'</option>').join('');return html.replace(/<td class="rb-product">[\s\S]*?<\/td>/,'<td class="rb-product"><select data-item="product" onchange="rcApplyProduct(this)"><option value="">Select product</option>'+options+'</select></td>')};
window.rcApplyProduct=function(select){const form=select.closest('form'),row=select.closest('.rb-item'),p=rcDocs('retail-product').find(x=>x.name===select.value);if(!p)return;const purity=row.querySelector('[data-item="purity"]');if(purity&&purity.tagName==='SELECT'){if(![...purity.options].some(o=>Number(o.value)===n(p.purity)))purity.add(new Option(p.purity+'K',p.purity));purity.value=p.purity}for(const [key,value] of [['wastage',p.wastage],['makingRate',p.makingRate],['rate',v2RateForPurity(p.purity)]]){const field=row.querySelector('[data-item="'+key+'"]');if(field&&n(value)>0)field.value=value}rbMarkDirty(form);rbRecalc(form)};
function rcRecalc(){const form=document.getElementById('rcEstimateForm');if(!form)return;const items=rcRows(),subtotal=items.reduce((s,x)=>s+x.subtotal,0),discount=n(form.elements.discount.value),discounted=Math.max(0,subtotal-discount),gstOn=form.elements.gstEnabled.checked,gstRate=gstOn?n(form.elements.gstRate.value):0,gst=rbRound(discounted*gstRate/100),gold=n(form.elements.exchangeGross.value)*n(form.elements.exchangeTesting.value)/100*n(form.elements.exchangeRate.value),final=rbRound(discounted+gst-gold);items.forEach((x,i)=>{const o=document.querySelectorAll('.rc-line-value')[i];if(o)o.value=rateMoney(x.subtotal)});for(const [id,val] of [['rcSubtotal',subtotal],['rcDiscount',discount],['rcGST',gst],['rcOldGold',gold],['rcFinal',final]]){const e=document.getElementById(id);if(e)e.textContent=rateMoney(val)}const weight=items.reduce((s,x)=>s+x.netWeight,0);document.getElementById('rcTotalWeight').textContent=fmt(weight)+' g';}
window.rcRemoveItem=function(b){if(document.querySelectorAll('#rcItems .rc-item').length<2)return say('Keep at least one jewellery item.');b.closest('.rc-item').remove();rcRecalc()};
window.rcAddItem=function(item){document.getElementById('rcItems').insertAdjacentHTML('beforeend',rcItemRow(item||{}));rcRecalc()};

function rcChitOptions(customerId='',selected=''){const maps=rcDocs('retail-chit-mapping').filter(m=>!customerId||m.customerId===customerId);return '<option value="">No chit linked</option>'+maps.map(m=>{const t=rcDocs('retail-chit-type').find(z=>z.id===m.typeId);return '<option value="'+esc(m.id)+'" '+(m.id===selected?'selected':'')+'>'+esc(m.chitNumber)+' · '+esc(t?.name||'Chit')+'</option>'}).join('')}
function rcChitSelect(customerId='',selected='',name='chitMappingId'){return '<label>Chit Info<select name="'+name+'"><option value="">No chit linked</option>'+rcDocs('retail-chit-mapping').filter(m=>!customerId||m.customerId===customerId).map(m=>{const t=rcDocs('retail-chit-type').find(z=>z.id===m.typeId);return '<option value="'+esc(m.id)+'" '+(m.id===selected?'selected':'')+'>'+esc(m.chitNumber)+' · '+esc(t?.name||'Chit')+'</option>'}).join('')+'</select></label>'}
function rcQuoteForm(){const q=rcDocs('retail-estimate').find(x=>x.id===rcEstimateEdit),items=q?.items?.length?q.items:[{}],rates=n(db.rates.gold24)||0;return '<form id="rcEstimateForm" class="rc-form" oninput="rcRecalc()" onchange="rcRecalc()" onsubmit="rcSaveEstimate(event)"><input type="hidden" name="id" value="'+esc(q?.id||'')+'"><section class="panel"><div class="rc-section-title"><h2>'+ (q?'Edit estimate / quotation':'New estimation / quotation')+'</h2><span>'+esc(q?.status||'Draft')+'</span></div><div class="rc-grid"><label>Quotation number<input name="documentNo" maxlength="60" value="'+esc(q?.documentNo||'')+'" placeholder="Auto generated"></label><label>Date & time<input required name="when" type="datetime-local" value="'+esc(q?.when||rbNow())+'"></label><label>Customer<select name="customerId" required><option value="">Select retail customer</option>'+db.customers.map(c=>'<option value="'+esc(c.id)+'" '+(c.id===q?.customerId?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></label>'+rcChitSelect(q?.customerId||'',q?.chitMappingId)+'<label>Valid until<input name="validUntil" type="date" value="'+esc(q?.validUntil||'')+'"></label><label>Reference<input name="reference" value="'+esc(q?.reference||'')+'"></label><label>24K rate ₹/g<input name="goldRate" type="number" min="0" step=".01" required value="'+(q?.goldRate??rates)+'"></label></div></section><section class="panel"><div class="rc-section-title"><h2>Jewellery items</h2><button type="button" onclick="rcAddItem()">＋ Add item</button></div><div id="rcItems">'+items.map(rcItemRow).join('')+'</div><div class="rc-weight">Total net weight <b id="rcTotalWeight">0.000 g</b></div></section><section class="panel"><div class="rc-section-title"><h2>Adjustments</h2><label class="rc-check"><input name="gstEnabled" type="checkbox" '+(q?.gstEnabled?'checked':'')+'> GST</label></div><div class="rc-grid"><label>Discount ₹<input name="discount" type="number" min="0" step=".01" value="'+(q?.discount||0)+'"></label><label>GST %<input name="gstRate" type="number" min="0" max="100" step=".01" value="'+(q?.gstRate||3)+'"></label><label>Old gold product<input name="exchangeProduct" value="'+esc(q?.exchangeProduct||'')+'" placeholder="Optional"></label><label>Old gold gross g<input name="exchangeGross" type="number" min="0" step=".001" value="'+(q?.exchangeGross||0)+'"></label><label>Old gold testing %<input name="exchangeTesting" type="number" min="1" max="100" step=".01" value="'+(q?.exchangeTesting||0)+'"></label><label>Old gold rate ₹/g<input name="exchangeRate" type="number" min="0" step=".01" value="'+(q?.exchangeRate??rates)+'"></label><label class="rc-wide">Notes<textarea name="notes" rows="2">'+esc(q?.notes||'')+'</textarea></label></div><div class="rc-totals"><span>Items <b id="rcSubtotal">₹ 0.00</b></span><span>Discount <b id="rcDiscount">₹ 0.00</b></span><span>GST <b id="rcGST">₹ 0.00</b></span><span>Old gold credit <b id="rcOldGold">₹ 0.00</b></span><strong>Estimate total <b id="rcFinal">₹ 0.00</b></strong></div></section><div class="rc-actions"><button type="button" onclick="rcPrintEstimate()">PDF / Print</button><button type="button" onclick="rcResetEstimate()">New</button><button class="primary">'+(q?'Save changes':'Save quotation')+'</button></div></form><section class="panel"><h2>Estimation / quotation history</h2>'+rcEstimateHistory()+'</section>'}
function rcEstimateHistory(){const all=rcDocs('retail-estimate').sort((a,b)=>String(b.when).localeCompare(String(a.when)));return all.length?table(['Quote','Date','Customer','Items','Amount','Status',''],all.map(q=>[esc(q.documentNo),esc(String(q.when||'').replace('T',' ')),esc(accountName(q.customerId,'customer')),q.items.length,rateMoney(q.amount),esc(q.status),'<button type="button" onclick="rcEditEstimate(\''+esc(q.id)+'\')">Edit</button> <button type="button" onclick="rcPrintSavedEstimate(\''+esc(q.id)+'\')">PDF</button> <button type="button" onclick="rcConvert(\''+esc(q.id)+'\')">Use in bill</button>'])):'<p class="muted">Saved quotations will appear here.</p>'}
window.rcEditEstimate=function(id){rcEstimateEdit=id;render()};window.rcResetEstimate=function(){if(!rbCanLeave())return;rcEstimateEdit='';render()};
function rcEstimateRead(form){const f=form.elements,items=rcRows();return {id:f.id.value||crypto.randomUUID(),kind:'retail-estimate',accountType:'customer',customerId:f.customerId.value,documentNo:f.documentNo.value.trim()||'Q-'+Date.now().toString(36).toUpperCase(),when:f.when.value,validUntil:f.validUntil.value,reference:f.reference.value.trim(),chitMappingId:f.chitMappingId.value||'',chitNumber:rcDocs('retail-chit-mapping').find(m=>m.id===f.chitMappingId.value)?.chitNumber||'',items,discount:n(f.discount.value),gstEnabled:f.gstEnabled.checked,gstRate:f.gstEnabled.checked?n(f.gstRate.value):0,exchangeProduct:f.exchangeProduct.value.trim(),exchangeGross:n(f.exchangeGross.value),exchangeTesting:n(f.exchangeTesting.value),goldRate:n(f.goldRate.value),exchangeRate:n(f.exchangeRate.value),notes:f.notes.value.trim(),amount:rbRound(Math.max(0,items.reduce((s,x)=>s+x.subtotal,0)-n(f.discount.value))*(1+(f.gstEnabled.checked?n(f.gstRate.value):0)/100)-n(f.exchangeGross.value)*n(f.exchangeTesting.value)/100*n(f.exchangeRate.value)),status:'Draft',createdAt:rcDocs('retail-estimate').find(x=>x.id===f.id.value)?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()}}
window.rcSaveEstimate=function(e){e.preventDefault();const f=e.target;if(!f.reportValidity())return;const d=rcEstimateRead(f);if(!d.customerId||!d.items.length||d.items.some(x=>!x.product||x.netWeight<=0||x.rate<=0||x.purity<1||x.purity>24))return say('Complete the customer and each item, including a valid purity from 1 to 100.');if(d.discount>d.items.reduce((s,x)=>s+x.subtotal,0))return say('Discount cannot exceed the item total.');if(f.elements.id.value&&!confirm('Save changes to this quotation?'))return;const i=db.retailDocuments.findIndex(x=>x.id===d.id);if(i<0)db.retailDocuments.push(d);else db.retailDocuments[i]=d;rcEstimateEdit='';const cloudSave=save();render();rcSaveStatus(cloudSave,'Retail quotation')};
function rcQuoteModel(q){const c=account(q.customerId,'customer'),items=q.items.map(x=>rbItemCalc(x)),totals=[['Items total',rateMoney(items.reduce((s,x)=>s+x.subtotal,0))],['Discount',rateMoney(q.discount)],...(q.gstEnabled?[['GST '+q.gstRate+'%',rateMoney(Math.max(0,items.reduce((s,x)=>s+x.subtotal,0)-q.discount)*q.gstRate/100)]]:[]),...(q.exchangeGross?[['Old gold · '+q.exchangeProduct,rateMoney(q.exchangeGross*q.exchangeTesting/100*q.exchangeRate)]]:[]),['ESTIMATE TOTAL',rateMoney(q.amount),true]];return {kind:'bill',retail:true,title:'ESTIMATION / QUOTATION',entityLabel:'Customer',entityName:c?.name||'Customer',entityDetails:[c?.address,c?.city,c?.phone].filter(Boolean).join(' · '),reference:q.documentNo,date:pdfDateText(q.when),entityDetails:[c?.address,c?.city,c?.phone,q.chitNumber?'Chit: '+q.chitNumber:''].filter(Boolean).join(' · '),taxEnabled:q.gstEnabled,invoiceItems:items.map(x=>Object.assign({},x,{purity:x.purity+'%'})),exchange:[],totals,notes:[q.validUntil?'Valid until '+q.validUntil:'',q.reference,q.notes].filter(Boolean).join(' · ')}}
window.rcPrintEstimate=function(){const f=document.getElementById('rcEstimateForm');if(!f?.reportValidity())return;const q=rcEstimateRead(f);if(!q.customerId||q.items.some(x=>!x.product||x.netWeight<=0))return say('Complete the customer and jewellery items before printing.');pdfPrintModel(rcQuoteModel(q),'retail')};window.rcPrintSavedEstimate=function(id){const q=rcDocs('retail-estimate').find(x=>x.id===id);if(q)pdfPrintModel(rcQuoteModel(q),'retail')};
window.rcConvert=function(id){const q=rcDocs('retail-estimate').find(x=>x.id===id);if(!q)return;if(!confirm('Open a new Retail sales bill with this quotation? You can review it before saving.'))return;rcSection='Bill';rcEstimateEdit='';rbOpen('Bill');setTimeout(()=>{const f=document.getElementById('customerSaleForm');if(!f)return;f.elements.partyId.value=q.customerId;syncSaleAccount(f);f.elements.when.value=q.when;f.elements.documentNo.value=q.documentNo;const tb=f.querySelector('#rbItemsTable');tb.querySelectorAll('.rb-item').forEach((r,i)=>{if(i)r.remove()});const first=tb.querySelector('.rb-item');first?.remove();tb.querySelector('tfoot').insertAdjacentHTML('beforebegin',q.items.map((x,i)=>rbItemMarkup(x,i)).join(''));f.elements.discountMode.value='amount';f.elements.discountValue.value=q.discount;f.elements.gstEnabled.checked=q.gstEnabled;f.elements.gstRate.value=q.gstRate||3;if(f.elements.chitMappingId)f.elements.chitMappingId.value=q.chitMappingId||'';if(q.exchangeGross>0){toggleOldGold(true);const row=document.querySelector('#oldGoldLines .exchange-line');if(row){row.querySelector('[data-exchange="product"]').value=q.exchangeProduct;row.querySelector('[data-exchange="weight"]').value=q.exchangeGross;row.querySelector('[data-exchange="testingPurity"]').value=q.exchangeTesting;row.querySelector('[data-exchange="rate"]').value=q.goldRate;}}rbMarkDirty(f);rbRecalc(f);},0)};
function rcProductsView(){const list=rcDocs('retail-product'),x=list.find(p=>p.id===rcProductEdit);return '<section class="panel"><h2>Retail product master</h2><p class="muted">Set up reusable jewellery products for estimates, tags and sales.</p><form class="rc-grid" onsubmit="rcSaveProduct(event)"><input type="hidden" name="id" value="'+esc(x?.id||'')+'"><label>Product name *<input name="name" required maxlength="100" value="'+esc(x?.name||'')+'"></label><label>Product group<input name="group" value="'+esc(x?.group||'')+'" placeholder="Rings, chains, bangles"></label><label>Purity K<input name="purity" type="number" min="1" max="24" step=".01" value="'+(x?.purity||22)+'"></label><label>Making charge / piece ₹<input name="makingRate" type="number" min="0" step=".01" value="'+(x?.makingRate||0)+'"></label><label>HSN<input name="hsn" value="'+esc(x?.hsn||'')+'"></label><label>Default wastage %<input name="wastage" type="number" min="0" max="100" step=".01" value="'+(x?.wastage||0)+'"></label><label class="rc-wide">Description<input name="description" value="'+esc(x?.description||'')+'"></label><div class="rc-actions rc-wide"><button class="primary">'+(x?'Update product':'Add product')+'</button><button type="button" onclick="rcProductEdit=\'\';render()">Clear</button></div></form></section><section class="panel"><h2>Products · '+list.length+'</h2>'+ (list.length?table(['Product','Group','Purity','Wastage','Making / piece','HSN',''],list.map(p=>[esc(p.name),esc(p.group||'—'),p.purity+'K',p.wastage+'%',rateMoney(p.makingRate),esc(p.hsn||'—'),'<button type="button" onclick="rcEditProduct(\''+esc(p.id)+'\')">Edit</button>'])):'<p class="muted">Add the first retail product above.</p>')+'</section>'}
window.rcEditProduct=id=>{rcProductEdit=id;render()};window.rcSaveProduct=function(e){e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),name=String(d.name||'').trim(),purity=n(d.purity);if(!name||purity<1||purity>24)return say('Enter a product name and purity from 1 to 100.');if(d.id&&!confirm('Save changes to this product?'))return;const old=rcDocs('retail-product').find(x=>x.id===d.id),p=Object.assign({},old||{},{id:d.id||crypto.randomUUID(),kind:'retail-product',accountType:'customer',name,group:String(d.group||'').trim(),purity,wastage:n(d.wastage),makingRate:n(d.makingRate),hsn:String(d.hsn||'').trim(),description:String(d.description||'').trim(),createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()}),i=db.retailDocuments.findIndex(x=>x.id===p.id);if(i<0)db.retailDocuments.push(p);else db.retailDocuments[i]=p;rcProductEdit='';const cloudSave=save();render();rcSaveStatus(cloudSave,'Retail product')};
function rcTaggingView(){const rows=rcDocs('retail-tagging'),x=rows.find(t=>t.id===rcTagEdit),prods=rcDocs('retail-product');return '<section class="panel"><h2>Retail product tagging</h2><p class="muted">Create or update a barcode/tag for an item. Tagged items can be selected in an estimate.</p><form class="rc-grid" onsubmit="rcSaveTag(event)"><input type="hidden" name="id" value="'+esc(x?.id||'')+'"><label>Tag / barcode *<input name="tagCode" required value="'+esc(x?.tagCode||'')+'"></label><label>Product name *<input name="product" list="rcProductNames" required value="'+esc(x?.product||'')+'"><datalist id="rcProductNames">'+prods.map(p=>'<option value="'+esc(p.name)+'">').join('')+'</datalist></label><label>Pieces<input name="pieces" type="number" min="1" step="1" value="'+(x?.pieces||1)+'"></label><label>Gross g *<input name="grossWeight" type="number" min=".001" step=".001" required value="'+(x?.grossWeight||'')+'"></label><label>Less g<input name="lessWeight" type="number" min="0" step=".001" value="'+(x?.lessWeight||0)+'"></label><label>Purity K *<input name="purity" type="number" min="1" max="24" step=".01" required value="'+(x?.purity||22)+'"></label><label>Wastage %<input name="wastage" type="number" min="0" max="100" step=".01" value="'+(x?.wastage||0)+'"></label><label>Rate / g ₹<input name="rate" type="number" min="0" step=".01" value="'+(x?.rate||v2RateForPurity(x?.purity||22))+'"></label><label>Making / piece ₹<input name="makingRate" type="number" min="0" step=".01" value="'+(x?.makingRate||0)+'"></label><label>Status<select name="status">'+rbOptions(['In stock','Reserved','Sold'],x?.status||'In stock')+'</select></label><label>Location<input name="location" value="'+esc(x?.location||'')+'"></label><label class="rc-wide">Remarks<input name="remarks" value="'+esc(x?.remarks||'')+'"></label><div class="rc-actions rc-wide"><button class="primary">'+(x?'Save tag':'Create tag')+'</button><button type="button" onclick="rcTagEdit=\'\';render()">Clear</button></div></form></section><section class="panel"><h2>Tagged items · '+rows.length+'</h2>'+ (rows.length?table(['Tag','Product','Pcs','Gross g','Purity','Wastage','Rate ₹/g','Status','Location',''],rows.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).map(t=>[esc(t.tagCode),esc(t.product),t.pieces,fmt(t.grossWeight),t.purity+'K',t.wastage+'%',rateMoney(t.rate),esc(t.status),esc(t.location||'—'),'<button type="button" onclick="rcEditTag(\''+esc(t.id)+'\')">Edit</button>'])):'<p class="muted">No items tagged yet.</p>')+'</section>'}
window.rcEditTag=id=>{rcTagEdit=id;render()};window.rcSaveTag=function(e){e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),code=String(d.tagCode||'').trim(),product=String(d.product||'').trim(),purity=n(d.purity),gross=n(d.grossWeight);if(!code||!product||gross<=0||purity<1||purity>24)return say('Enter a unique tag, product, positive weight and purity from 1 to 100.');if(rcDocs('retail-tagging').some(t=>t.id!==d.id&&t.tagCode.toLowerCase()===code.toLowerCase()))return say('That tag / barcode already exists.');if(d.id&&!confirm('Save changes to this tag?'))return;const old=rcDocs('retail-tagging').find(t=>t.id===d.id),tag=Object.assign({},old||{},{id:d.id||crypto.randomUUID(),kind:'retail-tagging',accountType:'customer',tagCode:code,product,pieces:n(d.pieces)||1,grossWeight:gross,lessWeight:n(d.lessWeight),purity,wastage:n(d.wastage),rate:n(d.rate),makingRate:n(d.makingRate),status:d.status,location:String(d.location||'').trim(),remarks:String(d.remarks||'').trim(),createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()}),i=db.retailDocuments.findIndex(t=>t.id===tag.id);if(i<0)db.retailDocuments.push(tag);else db.retailDocuments[i]=tag;rcTagEdit='';const cloudSave=save();render();rcSaveStatus(cloudSave,'Retail tag')};
